async function notifyFailure(env:Env,nodeId:number|null,dlqId:string|null):Promise<void> {
  const message={text:'DECOMMISSION generated Worker execution failed',timestamp:new Date().toISOString(),nodeId,dlqId};
  const endpoints:[string|undefined,'slack'|'discord'][]=[[env.SLACK_ERROR_WEBHOOK_URL,'slack'],[env.DISCORD_ERROR_WEBHOOK_URL,'discord']];
  for(const [address,kind] of endpoints){
    if(!address)continue;
    try {
      const url=new URL(address);
      if(url.protocol!=='https:'||url.username||url.password)continue;
      if(kind==='slack' && (url.hostname!=='hooks.slack.com'||!url.pathname.startsWith('/services/')))continue;
      if(kind==='discord' && (url.hostname!=='discord.com'||!url.pathname.startsWith('/api/webhooks/')))continue;
      const payload=kind==='slack'?{text:JSON.stringify(message)}:{content:JSON.stringify(message)};
      await fetch(url.toString(),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(2500),redirect:'error'});
    }catch{/* Delivery best-effort: never expose credentials, stack trace or webhook payload. */}
  }
}
async function recordFailure(raw:string,env:Env,error:unknown):Promise<string|null> {
  if(!env.DECOMMISSION_DLQ)return null;
  const key=`failed/${new Date().toISOString().slice(0,10)}/${crypto.randomUUID()}.json`;
  const data:DeadLetter={version:1,original:raw,createdAt:new Date().toISOString(),nodeId:error instanceof NodeFailure?error.nodeId:null,attempts:0};
  await env.DECOMMISSION_DLQ.put(key,JSON.stringify(data),{httpMetadata:{contentType:'application/json'}});
  return key;
}

class InputTooLarge extends Error {}

async function readBoundedUtf8(request:Request,maxBytes:number):Promise<string>{
  const declared=request.headers.get('content-length');

  if(declared!==null&&/^\d+$/.test(declared)&&Number(declared)>maxBytes){
    throw new InputTooLarge();
  }

  const reader=request.body?.getReader();
  if(!reader)return '';

  const decoder=new TextDecoder('utf-8',{fatal:true});
  let bytes=0;
  let text='';
  let completed=false;

  try{
    for(;;){
      const part=await reader.read();

      if(part.done){
        completed=true;
        break;
      }

      bytes+=part.value.byteLength;

      if(bytes>maxBytes){
        throw new InputTooLarge();
      }

      text+=decoder.decode(part.value,{stream:true});
    }

    return text+decoder.decode();
  }finally{
    if(!completed){
      try{
        void reader.cancel().catch(()=>{});
      }catch{}
    }

    reader.releaseLock();
  }
}

async function replay(request:Request,env:Env):Promise<Response>{
  if(!env.DECOMMISSION_DLQ||!env.DECOMMISSION_REPLAY_SECRET||env.DECOMMISSION_REPLAY_SECRET.length<32)
    return Response.json({error:'Replay not configured'},{status:404});
  if(!secretEquals(request.headers.get('x-decommission-replay-key')??'',env.DECOMMISSION_REPLAY_SECRET))
    return Response.json({error:'Unauthorized'},{status:401});
  if(!/^application\/json(?:;|$)/i.test(request.headers.get('content-type')??''))return Response.json({error:'JSON required'},{status:415});
  if(Number(request.headers.get('content-length')??'0')>4096)return Response.json({error:'Too large'},{status:413});
  let input:{id?:string;acknowledgeDuplicateSideEffects?:boolean};

  try{
    const raw=await readBoundedUtf8(request,4096);
    input=JSON.parse(raw);
  }catch(error){
    if(error instanceof InputTooLarge)
      return Response.json({error:'Too large'},{status:413});
    return Response.json({error:'Invalid replay request'},{status:400});
  }
  if(!input||typeof input!=='object'||Array.isArray(input))
    return Response.json({error:'Invalid replay request'},{status:400});
  const key=input.id;
  if(typeof key!=='string'||!/^failed\/\d{4}-\d{2}-\d{2}\/[0-9a-f-]{36}\.json$/.test(key))
    return Response.json({error:'Invalid DLQ identifier'},{status:400});
  if(input.acknowledgeDuplicateSideEffects!==true)
    return Response.json({
      error:'Replay requires acknowledgement that partial side effects may be duplicated'
    },{status:409,headers:{'Cache-Control':'no-store'}});
  const stored=await env.DECOMMISSION_DLQ.get(key);
  if(!stored)return Response.json({error:'Record not found'},{status:404});
  let data:DeadLetter;try{data=JSON.parse(await stored.text())}catch{return Response.json({error:'Corrupt DLQ record'},{status:503})}
  if(data.version!==1||typeof data.original!=='string'||data.original.length>1048576)return Response.json({error:'Invalid DLQ record'},{status:503});
  try{const result=await execute(JSON.parse(data.original),env);
    // Retain the original entry: automatic deletion may hide partial side-effects.
    return Response.json({replayed:true,retained:true,nodeId:data.nodeId,result:result.body},{status:200});
  } catch {return Response.json({error:'Replay execution failed; record retained'},{status:502})}
}
export default {
  async fetch(request:Request, env:Env): Promise<Response> {
    const path=new URL(request.url).pathname;
    if(request.method!=='POST')return Response.json({error:'POST required'},{status:405});
    if(path==='/replay')return replay(request,env);
    if(path!=='/')return Response.json({error:'Not found'},{status:404});
    if(!env.WEBHOOK_SECRET||!matches(request.headers.get('x-decommission-key')??'',env.WEBHOOK_SECRET))return Response.json({error:'Unauthorized'},{status:401});
    if(!/^application\/json(?:;|$)/i.test(request.headers.get('content-type')??''))return Response.json({error:'JSON required'},{status:415});
    if(Number(request.headers.get('content-length')??'0')>1048576)return Response.json({error:'Too large'},{status:413});
    let text:string;let input:unknown;
    try{
      text=await readBoundedUtf8(request,1048576);
      input=JSON.parse(text);
    }catch(error){
      if(error instanceof InputTooLarge)
        return Response.json({error:'Too large'},{status:413});
      return Response.json({error:'Invalid JSON'},{status:400});
    }
    try {
      const result=await execute(input,env);
      return Response.json(result.body,{status:result.status});
    } catch(error) {
      // No stack traces or payloads are forwarded to external alert providers.
      let key:string|null=null;
      try{key=await recordFailure(text,env,error)}
      catch{await notifyFailure(env,error instanceof NodeFailure?error.nodeId:null,null);return Response.json({error:'Execution failed; DLQ storage unavailable'},{status:503})}
      await notifyFailure(env,error instanceof NodeFailure?error.nodeId:null,key);
      return key?Response.json({stored:true,executionSucceeded:false,dlqId:key},{status:202})
        :Response.json({error:'Execution failed; no DLQ configured'},{status:502});
    }
  }
};
